const puppeteer = require('puppeteer');
const path = require('path');

async function renderPoster() {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  const page = await browser.newPage();
  await page.setViewport({
    width: 794,
    height: 1123,
    deviceScaleFactor: 2
  });

  const htmlPath = path.resolve('/app/output/Global-Internet-Usage-infographic.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.waitForTimeout(2000);

  // Take screenshot and save as PNG
  await page.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
    fullPage: true
  });

  await browser.close();
  console.log('Poster saved to /app/output/final_poster.png');
}

renderPoster().catch(console.error);

